    # By default convert_underscores=True. 
    # It should accept 'my-header' and NOT accept 'my_header'.

    # Test hyphenated header (should work)
    response = client.get("/", headers={"my-header": "hyphenated"})
    assert response.json() == {"my_header": "hyphenated"}

    # Test underscored header (should NOT work if convert_underscores=True)
    response = client.get("/", headers={"my_header": "underscored"})
    print(f"Response with underscored header: {response.json()}")
    # If the bug exists, this might be {"my_header": "underscored"}
    # We want it to be {"my_header": None}

